const read = (p) => import(pathToFileURL(`${root}/apps/daemon/src/${p}.js`));
const { createDaemonCommandPorts } = await read('daemon-command-registry');
const { readDurableLedger, stateOf } = await read('bootstrap/bootstrap-ledger');
const { handleCommandRequest, handleAsyncCommandRequest } = await read('http/http-adapter');
const { WIRE_PROTOCOL_VERSION } = await read('http/http-contract');
const { CONTROLLED_PROFILE_VERSION } = await read('repository/controlled-profile/controlled-profile-generator');
const temp = mkdtempSync(join(tmpdir(), 'moe-disclosure-measure-'));
const projectId = 'project-disclosure-probe';
let store;
try {
  store = SqliteEventStore.openForProject(join(temp, 'store.sqlite'), projectId);
  const ports = createDaemonCommandPorts({ store, projectId, operatorPrincipalId: 'operator',
    clock: () => '2026-09-06T07:40:00.000Z', repositoryBootstrap: {
      catalog: async () => {}, gh: { create: async () => { throw new Error('probe failure'); } }
    } });
  const deps = { registry: ports.registry, decisions: ports.decisions, authenticator: {
    authenticate: () => ({ verdict: 'AUTHENTICATED', principal: {
      projectId, principalId: 'operator', capabilities: ['project.admin'] } }) } };
  const request = (id, kind, payload) => ({ credential: 'local-probe', protocolVersion: WIRE_PROTOCOL_VERSION,
    body: new TextEncoder().encode(JSON.stringify({ commandId: id, commandKind: kind,
      correlationId: 'probe-correlation', expectedVersion: 0, payload, requestDigest: 'b'.repeat(64),
      schemaVersion: RUNTIME_COMMAND_ENVELOPE_VERSION, sessionCredential: 'local-probe', targetAggregateId: 'probe' })) });
  assert.equal(handleCommandRequest(deps, request('register','project.register',{owner:'probe'}), 'HTTP_LISTENER').outcome,'ACCEPTED');
  const command = await handleAsyncCommandRequest(deps, request('bootstrap','repository.bootstrap', {
    dir: join(temp,'product'), productName:'probe-product', profileVersion:CONTROLLED_PROFILE_VERSION,
    github:{owner:'probe-owner',name:'probe-product',visibility:'private'} }), 'HTTP_LISTENER');
  assert.equal(command.outcome,'ACCEPTED');
  const receipt = stateOf(readDurableLedger(store,projectId),`${projectId}-bootstrap`);
  console.log(JSON.stringify(receipt));
  assert.equal(receipt.outcome,'BOOTSTRAPPED');
  assert.equal(receipt.refusal,null);
  assert.match(receipt.sha,/^[0-9a-f]{40}$/);
  assert.equal(receipt.githubRefusal.code,'BOOTSTRAP_GH_UNAVAILABLE');
  assert.equal(receipt.githubRefusal.detail,'GH_EXECUTION_FAILED');
} finally {
  try { store?.close(); } finally { rmSync(temp,{recursive:true,force:true}); }
}

